mapper.select:
SELECT u.user_no AS id, u.nickname FROM ultary_user u
WHERE  AND u.user_no > #{cursorId}
ORDER BY u.user_no LIMIT #{limit}

SELECT f.feed_id AS id FROM ultary_feed f JOIN ultary_user u ON u.user_no=f.user_no
WHERE  AND f.is_deleted=0 AND f.visibility='PUBLIC' AND f.feed_id > #{cursorId}
ORDER BY f.feed_id LIMIT #{limit}
